local presets={PALADIN=data,HUNTER=hunter,ROGUE=rogue,WARRIOR=warrior,SHAMAN=shaman,PRIEST=priest,MAGE=mage,WARLOCK=warlock,DRUID=druid}
function M.Get(class)return presets[class or Class()]end
function M.Source()return KerimAnkaUIBarsAPI and KerimAnkaUIBarsAPI.BartenderActive()and'bartender'or'blizzard'end
local refresh
local function TryRefresh()
 local r=refresh;if not r or Combat()then return end
 local current=Pack(GetActionBarToggles());local ready=Settings and Settings.GetSetting and Settings.NotifyUpdate
 if ready then ready=Settings.GetSetting('PROXY_SHOW_ACTIONBAR_2')and Settings.GetSetting('PROXY_SHOW_ACTIONBAR_3')end
 for i=1,r.expected.n do if current[i]~=r.expected[i]then ready=false;break end end
 if ready then
  refresh=nil
  local ok,err=pcall(function()Settings.NotifyUpdate('PROXY_SHOW_ACTIONBAR_2');Settings.NotifyUpdate('PROXY_SHOW_ACTIONBAR_3')end)
  M.barRefreshError=not ok and tostring(err)or nil;return
 end
 r.attempts=r.attempts+1
 if r.attempts<20 and C_Timer and C_Timer.After then C_Timer.After(.25,function()if refresh==r then TryRefresh()end end)else refresh=nil end
end
function M.RefreshNativeBars(expected)
 if not GetActionBarToggles then return end
 refresh={expected=Copy(expected or Pack(GetActionBarToggles())),attempts=0};TryRefresh()
end
function M.Capture()
 if not GetActionBarToggles or not SetActionBarToggles then return nil,'flUnavailable'end
 local bars=Pack(GetActionBarToggles())
 if bars.n<2 or bars.n>8 then return nil,'flUnavailable'end
 for i=1,bars.n do if type(bars[i])~='boolean'then return nil,'flUnavailable'end end
 return{bars=bars}
end
function M.CaptureProfileSetup()return M.Capture()end
function M.Prepare(class)
 if Combat()then return nil,'combatLock'end
 if not M.Get(class)or class~=Class()then return nil,'readyMissing'end
 return M.Capture()
end
function M.Restore(snapshot)
 if Combat()or type(snapshot)~='table'then return false end
 local bars=snapshot.bars
 if not bars then return true end
 if not GetActionBarToggles or not SetActionBarToggles or type(bars.n)~='number'or bars.n<2 or bars.n>8 or bars.n%1~=0 then return false end
 for i=1,bars.n do if type(bars[i])~='boolean'then return false end end
 SetActionBarToggles(unpack(bars,1,bars.n));M.RefreshNativeBars(bars);return true
end
function M.Commit(action)
 if Combat()then return false,'combatLock'end
 if action.setupRestore then return M.Restore(action.setupRestore)end
 if action.class~=Class()or not M.Get(action.class)then return false,'readyMissing'end
 local before=action.setupBefore;if not before or not before.bars then return false,'readyApplyFailed'end
 local bars=Copy(before.bars);bars[1]=true;bars[2]=true
 local ok=pcall(function()
  SetActionBarToggles(unpack(bars,1,bars.n))
  local current=Pack(GetActionBarToggles())
  for i=1,bars.n do assert(current[i]==bars[i],'native action bar toggle mismatch')end
  M.RefreshNativeBars(bars)
 end)
 if not ok then pcall(M.Restore,before);return false,'readyApplyFailed'end
 return true
end
function M.LockPortable(payload)
 local root=payload.settings.root;root.microLocked=true
 for _,key in ipairs({'fps','soundShortcut','bagShortcut','minimapButtons','experience','classicSwing','classicCast'})do root[key]=root[key]or{};root[key].locked=true end
 root.minimapControls=root.minimapControls or{};root.minimapControls.clockLocked=true
 for _,key in ipairs({'KAClassic_ForeverLeatherUnitsDB','KAClassic_ForeverThreatDB','KAClassic_ForeverHunterRangeDB','KAClassic_HunterAspectAlertCharacterDB'})do
  local d=payload.settings[key];if d then d.locked=true end
 end
 local units=payload.settings.KAClassic_ForeverLeatherUnitsDB
 if units then units.comboDetached=units.comboDetached or{};units.comboDetached.locked=true end
 return payload
end
function M.Queue()
 if Combat()then return false,'combatLock'end
 if K.db.profileTransaction then return false,'pfPendingProfile'end
 local d=M.Get();if not d then return false,'readyMissing'end
 local payload,err=K.Profiles.Decode(d.ui);if not payload then return false,err end
 M.LockPortable(payload);payload.settings.root.barSource=0
 -- Decorate the bars selected by this class preset.
 for _,key in ipairs({'KAClassic_ForeverHunterArtCharacterDB','KAClassic_ForeverBarBackdropCharacterDB'})do
  local settings=payload.settings[key]
  if settings then settings.bars=Copy(d.bars or {1,2,3});settings.classicBartenderInitialized=true end
 end
 local code;code,err=K.Profiles.Encode(payload);if not code then return false,err end
 local layouts=K.ProfileLayouts;if not layouts then return false,'plInvalid'end
 local setup,setupError=M.Capture();if not setup then return false,setupError end
 setup.bars[1]=true;setup.bars[2]=true
 local snapshot=layouts.Encode({version=1,editMode={code=d.layout,name='KerimAnka UI Classic '..d.name,kind=Enum.EditModeLayoutType.Account},setup=setup,bartender=Copy(d.bartender)})
 if not snapshot then return false,'plInvalid'end
 return layouts.Queue({code=code,layouts=snapshot,name='KerimAnka UI Classic '..d.name},'KerimAnka UI Classic '..d.name)
end
function M.Draw(page,w,y)
 local d=M.Get();M.readyCard=nil;if not d then return y end
 local box=w.Box(page,0,y,714,208);M.readyCard=box
 w.Text(box,K.L('ready'..d.name..'Title'),16,-14,680,17,{.87,.73,.40})
 local help=w.Text(box,K.L('ready'..d.name..'Help'),16,-46,680,13,{.65,.70,.62})
 w.Text(box,K.L(M.Source()=='blizzard'and'readyUsesNative'or'readyUsesBT'),16,-118,680,13,{.87,.73,.40})
 local armed=false;local cancel
 local button=w.Button(box,K.L('readyApply'..d.name),16,-160,682,34,function(self)
  if Combat()or K.db.profileTransaction then return end
  if not armed then armed=true;help:SetText(K.L('readyConfirmWarning'));self.label:SetText(K.L('readyConfirmApply'));self:SetWidth(510);cancel:Show();return end
  local ok,err=M.Queue()
  if ok then K.Reload()else M.status=err;if K.Message then K.Message(err)end;if K.Render then K.Render()end end
 end)
 local function Reset()armed=false;help:SetText(K.L('ready'..d.name..'Help'));button.label:SetText(K.L('readyApply'..d.name));button:SetWidth(682);cancel:Hide()end
 cancel=w.Button(box,K.L('readyConfirmCancel'),538,-160,160,34,Reset);cancel:Hide()
 button:SetScript('OnHide',function()if armed then Reset()end end)
 if Combat()or K.db.profileTransaction then button:Disable()end
 if M.status then w.Text(page,K.L(M.status),8,y-220,690,13,{.87,.73,.40});return y-280 end
 return y-230
end
function M.PrepareReload()return true end
function M.CancelPreparedReload()return true end
local events=CreateFrame('Frame')
for _,event in ipairs({'SETTINGS_LOADED','PLAYER_REGEN_ENABLED'})do events:RegisterEvent(event)end
events:SetScript('OnEvent',function()if refresh then TryRefresh()end end)
